// Code should be written in Go/Golang
// Write a function to find sequences of lowercase letters joined with an underscore.
// Examples:
// >>> text_lowercase_underscore("aab_cbbbc")
// >>> ('Found a match!')
// >>> text_lowercase_underscore("aab_Abbbc")
// >>> ('Not matched!')
// >>> text_lowercase_underscore("Aaab_abbbc")
// >>> ('Not matched!')
func text_lowercase_underscore (text string) string {
	if len(text) == 0 {
		return "Not matched!"
	}
	for i := 0; i < len(text); i++ {
		if text[i] == '_' {
			if i == 0 || i == len(text) - 1 {
				return "Not matched!"
			}
			if text[i-1] >= 'a' && text[i-1] <= 'z' && text[i+1] >= 'a' && text[i+1] <= 'z' {
				return "Found a match!"
			}
		}
	}
	return "Not matched!"
}
