// Write a golang function to find binomial co-efficient.
// Examples:
// >>> binomial_Coeff(5,2)
// >>> 10
// >>> binomial_Coeff(4,3)
// >>> 4
// >>> binomial_Coeff(3,2)
// >>> 3
func binomial_Coeff (n int, k int) int {
	if k > n {
		return 0
	}
	if k == 0 || k == n {
		return 1
	}
	return binomial_Coeff(n-1, k-1) + binomial_Coeff(n-1, k)
}
