// >>> 5
// >>> max_Prime_Factors(6)
// >>> 3
// >>> max_Prime_Factors(2)
// >>> 2
func max_Prime_Factors (n int) int {
	var maxPrimeFactor int
	for i := 2; i <= int(math.Sqrt(float64(n))); i++ {
		if n % i == 0 {
			maxPrimeFactor = i
			n = n / i
			i = 1
		}
	}
	if maxPrimeFactor < n {
		maxPrimeFactor = n
	}
	return maxPrimeFactor
}
