	var strs []string
	for _, v := range mixed_list {
		switch v.(type) {
		case int:
			ints = append(ints, v.(int))
		case string:
			strs = append(strs, v.(string))
		}
	}
	sort.Ints(ints)
	sort.Strings(strs)
	var result []interface{}
	for _, v := range ints {
		result = append(result, v)
	}
	for _, v := range strs {
		result = append(result, v)
	}
	return result
