// Code should be written in Go/Golang
// Write a function to find sequences of lowercase letters joined with an underscore using regex.
// Examples:
// >>> text_match("aab_cbbbc")
// >>> 'Found a match!'
// >>> text_match("aab_Abbbc")
// >>> 'Not matched!'
// >>> text_match("Aaab_abbbc")
// >>> 'Not matched!'
func text_match (text string) string {
	if len(text) == 0 {
		return "Not matched!"
	}
	if len(text) == 1 {
		if text[0] >= 'a' && text[0] <= 'z' {
			return "Found a match!"
		}
		return "Not matched!"
	}
	if text[0] >= 'a' && text[0] <= 'z' {
		if text[1] >= 'a' && text[1] <= 'z' {
			return "Found a match!"
		}
		if text[1] == '_' {
			return text_match(text[2:])
		}
	}
	return "Not matched!"
}
