// Code should be written in Go/Golang
// Write a golang function to find the minimum element in a sorted and rotated array.
// Examples:
// >>> find_Min([1,2,3,4,5],0,4)
// >>> 1
// >>> find_Min([4,6,8],0,2)
// >>> 4
// >>> find_Min([2,3,5,7,9],0,4)
// >>> 2
func find_Min (arr []int, low int, high int) int {
	if low == high {
		return arr[low]
	}
	if low + 1 == high {
		if arr[low] < arr[high] {
			return arr[low]
		} else {
			return arr[high]
		}
	}
	mid := (low + high) / 2
	if arr[low] < arr[mid] {
		return find_Min(arr, low, mid)
	} else {
		return find_Min(arr, mid, high)
	}
}
