// Write a function to find the maximum sum in the given right triangle of numbers.
// Examples:
// >>> max_sum([[1], [2,1], [3,3,2]], 3)
// >>> 6
// >>> max_sum([[1], [1, 2], [4, 1, 12]], 3)
// >>> 15
// >>> max_sum([[2], [3,2], [13,23,12]], 3)
// >>> 28
func max_sum (tri [][]int, n int) int {
	// Write your code here
	// return 0
	if n == 1 {
		return tri[0][0]
	}
	if n == 2 {
		return tri[0][0] + tri[1][1]
	}
	for i := 2; i < n; i++ {
		for j := 0; j < i; j++ {
			if j == 0 {
				tri[i][j] += tri[i-1][j]
			} else if j == i-1 {
				tri[i][j] += tri[i-1][j-1]
			} else {
				tri[i][j] += max(tri[i-1][j-1], tri[i-1][j])
			}
		}
	}
	return max(tri[n-1][0], tri[n-1][n-1])
}
