// >>> babylonian_squareroot(2)
// >>> 1.414213562373095
// >>> babylonian_squareroot(9)
// >>> 3.0
func babylonian_squareroot (number int) float64 {
	var x float64 = float64(number)
	var y float64 = 1
	var e float64 = 0.000001
	for {
		x = (x + y) / 2
		y = number / x
		if x - y < e {
			break
		}
	}
	return x
}
