// >>> 7
// >>> lps("PART OF THE JOURNEY IS PART")
// >>> 9
func lps (str string) int {
	// Write your code here
	// return 0
	var dp [][]int
	for i := 0; i < len(str); i++ {
		dp = append(dp, make([]int, len(str)))
	}
	for i := len(str) - 1; i >= 0; i-- {
		for j := i; j < len(str); j++ {
			if i == j {
				dp[i][j] = 1
			} else if str[i] == str[j] {
				dp[i][j] = dp[i+1][j-1] + 2
			} else {
				dp[i][j] = max(dp[i+1][j], dp[i][j-1])
			}
		}
	}
	return dp[0][len(str)-1]
}
