// >>> 10
// >>> max_profit([2, 4, 7, 5, 4, 3, 5], 2)
// >>> 7
// >>> max_profit([10, 6, 8, 4, 2], 2)
// >>> 2
func max_profit (price []int, k int) int {
	// Write your code here
	if len(price) == 0 {
		return 0
	}
	if k > len(price) {
		k = len(price)
	}
	dp := make([][]int, k+1)
	for i := 0; i < k+1; i++ {
		dp[i] = make([]int, len(price))
	}
	for i := 1; i < k+1; i++ {
		for j := 1; j < len(price); j++ {
			dp[i][j] = max(dp[i][j-1], price[j] - price[j-1] + dp[i-1][j-1])
		}
	}
	return dp[k][len(price)-1]
}
