func find_Min_Sum (num int) interface{} {
	var sum int
	var min int
	var min_sum int
	var factors []int
	for i := 1; i <= num; i++ {
		if num % i == 0 {
			factors = append(factors, i)
		}
	}
	for i := 0; i < len(factors); i++ {
		sum = 0
		for j := 0; j < len(factors); j++ {
			if factors[i] % factors[j] == 0 {
				sum += factors[j]
			}
		}
		if i == 0 {
			min = sum
			min_sum = factors[i]
		} else {
			if sum < min {
				min = sum
				min_sum = factors[i]
			}
		}
	}
	return min_sum
}
