// Examples:
// >>> jacobsthal_lucas(5)
// >>> 31
// >>> jacobsthal_lucas(2)
// >>> 5
// >>> jacobsthal_lucas(4)
// >>> 17
func jacobsthal_lucas (n int) int {
	if n == 0 {
		return 0
	}
	if n == 1 {
		return 1
	}
	return jacobsthal_lucas(n-1) + 2*jacobsthal_lucas(n-2)
